<?php
require __DIR__.'/core.php';require __DIR__.'/profile-core.php';require __DIR__.'/staff-core.php';require __DIR__.'/staff-invite-core.php';
$_SERVER['SCRIPT_NAME']=preg_replace('~/account/staff-access\.php$~','/account/index.php',$_SERVER['SCRIPT_NAME']);
$error='';$notice='';$b=null;$staff=[];$invitations=[];
try{
 start();user();$b=business();if(!$b)go('business');
 if(($_SESSION['business_context']['role']??'')!=='owner')throw new RuntimeException('Only the owner can manage access.');
 $scope=['p_business'=>$b['id'],'p_environment'=>profile_env()];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();$action=(string)($_POST['action']??'invite');
  if($action==='invite'){
   staff_invite_send($scope,staff_id((string)($_POST['staff']??'')),(string)($_POST['role']??''),($_POST['replace']??'')!==''?staff_id((string)$_POST['replace']):null);
   $notice='Invitation queued. Email status is shown below.';
  }elseif($action==='revoke'){
   api('/rest/v1/rpc/business_staff_invite_revoke',$scope+['p_id'=>staff_id((string)($_POST['id']??''))],'POST',$_SESSION['auth']['access_token']);$notice='Invitation revoked.';
  }elseif($action==='offboard'){api('/rest/v1/rpc/business_staff_offboard',$scope+['p_staff'=>staff_id((string)($_POST['staff']??''))],'POST',$_SESSION['auth']['access_token']);$notice='Staff deactivated and business access revoked. History retained.';}else throw new RuntimeException('Choose a valid action.');
 }
 $staff=staff_rows($b);if(isset($_GET['staff'])){$selected=staff_id((string)$_GET['staff']);$staff=array_values(array_filter($staff,fn($s)=>$s['id']===$selected));}$invitations=api('/rest/v1/rpc/business_staff_invite_list',$scope,'POST',$_SESSION['auth']['access_token']);
}catch(AccountSessionExpired $e){go('signin');}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Staff invitations unavailable. Check details and configuration before retrying.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Staff access | FaraiOS</title><link rel="icon" href="../favicon.svg"><link rel="stylesheet" href="../business/profile.css"><link rel="stylesheet" href="layout.css"><script src="layout.js" defer></script><link rel="stylesheet" href="private.css"><link rel="stylesheet" href="../ui/design-system.css"><link rel="stylesheet" href="staff-onboarding.css?v=workspace-20261115"></head><body class="ui-page ui-workspace business-page staff-access-page"><?php require_once __DIR__.'/layout.php';app_layout('Staff',$b);?><main id="app-main" tabindex="-1" class="editor-main staff-access-main">
<header class="staff-access-heading"><div><a class="staff-back" href="staff.php">← Staff</a><h1>Staff access</h1><p class="staff-scope"><?=esc($b['name']??'')?> <span class="staff-scope-tag"><?=esc($scope['p_environment']??'')?></span></p></div><a class="staff-settings-link" href="access.php">Access settings</a></header>
<?php if($error):?><p class="alert" role="alert"><?=esc($error)?></p><?php endif;if($notice):?><p class="notice" role="status"><?=esc($notice)?></p><?php endif;?>
<section class="panel staff-access-toolbar" aria-label="Find staff"><div class="staff-search-field"><label for="search">Search staff</label><input id="search" type="search" placeholder="Name or email" autocomplete="off" aria-describedby="staff-search-scope"><p id="staff-search-scope">Live and preview are separate.</p></div><p id="matches" role="status"></p></section>
<div class="staff-access-list">
<?php foreach($staff as $s):$current=null;foreach($invitations as $i)if($i['staff_id']===$s['id']&&in_array($i['status'],['Pending','Active'])){$current=$i;break;}?><section class="panel staff-result staff-access-card" data-search="<?=esc(strtolower($s['name'].' '.$s['email']))?>"><div class="staff-card-heading"><div><h2><?=esc($s['name'])?></h2><p class="staff-email"><?=esc($s['email']?:'No email saved')?></p></div><div class="staff-card-badges"><span class="staff-status <?=$s['active']?'is-active':'is-inactive'?>"><?=$s['active']?'Active staff':'Inactive staff'?></span><?php if($current):?><span class="staff-status is-access"><?=esc($current['status'])?> access</span><?php endif;?></div></div>
<?php if($s['active']&&$s['email']!==''&&!$current):?><div class="staff-invite-compose"><?php form_start();?><input type="hidden" name="staff" value="<?=esc($s['id'])?>"><div class="staff-role-field"><label>Role<select name="role" required><option value="">Choose role</option><option value="worker">Worker — assigned jobs</option><option value="receptionist">Receptionist</option><option value="manager">Manager</option></select></label></div><p class="staff-invite-scope"><?=esc($b['name'])?> · <?=esc($scope['p_environment'])?>. Access starts after acceptance.</p><label class="staff-confirm"><input type="checkbox" required> Confirm recipient, role and business.</label><button class="button">Send invitation</button></form></div><?php elseif($current):?><p class="staff-access-note">Invitation and access details below. <a href="access.php">Manage roles</a></p><?php else:?><p class="staff-access-note">Email and active staff status required. <a href="staff.php">Edit staff</a></p><?php endif;?>
<div class="staff-invitation-list"><?php foreach($invitations as $i):if($i['staff_id']===$s['id']):?><div class="staff-invite-row"><div class="staff-invite-info"><div class="staff-invite-tags"><span class="staff-role"><?=esc($i['role'])?></span><span class="staff-status is-access"><?=esc($i['status'])?></span><span class="staff-delivery" title="Provider acceptance does not confirm inbox delivery">Email: <?=esc(str_replace('_',' ',$i['delivery']))?></span></div><p class="staff-invite-recipient"><?=esc($i['email'])?></p></div><div class="staff-invite-actions"><?php if($i['status']==='Pending'):form_start();?><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=esc($i['id'])?>"><button class="button staff-danger">Revoke invitation</button></form><?php endif;if(in_array($i['status'],['Pending','Expired'])):form_start();?><input type="hidden" name="action" value="invite"><input type="hidden" name="staff" value="<?=esc($s['id'])?>"><input type="hidden" name="role" value="<?=esc($i['role'])?>"><input type="hidden" name="replace" value="<?=esc($i['id'])?>"><button class="button staff-secondary" title="Replaces the previous invitation link">Resend link</button></form><?php endif;?></div></div><?php endif;endforeach;?></div>
<details class="staff-management"><summary>Manage access</summary><?php if(!$current):?><p>No access granted.</p><?php endif;form_start();?><input type="hidden" name="action" value="offboard"><input type="hidden" name="staff" value="<?=esc($s['id'])?>"><label class="staff-confirm"><input type="checkbox" required> Deactivate staff and revoke access</label><p class="muted">Cancels pending invites. Keeps history.</p><button class="button staff-danger">Deactivate &amp; revoke</button></form></details></section><?php endforeach;?>
</div><script src="staff-search.js?v=compact-20261115" defer></script></main><footer>© <?=date('Y')?> FaraiOS</footer></body></html>
